INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 70, $${"id": "WE-06", "kind": "we", "part": "Written Expression", "tokens": ["The train ", "already left", " before I ", "arrived", " at the station", "."], "marks": [0, 1, 3, 4], "answer": "B", "explanation": "Kereta sudah berangkat sebelum saya tiba di stasiun, jadi kejadian yang terjadi lebih dulu memakai past perfect: 'had already left', bukan 'already left'.", "topic": "verb tense (past perfect)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 71, $${"id": "WE-07", "kind": "we", "part": "Written Expression", "tokens": ["Each of the students ", "must submit", " their", " assignment by Friday", "."], "marks": [0, 1, 2, 3], "answer": "C", "explanation": "'Each' itu singular, jadi pronominanya harus singular juga: 'his or her', bukan 'their' yang jamak.", "topic": "pronoun agreement"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 72, $${"id": "WE-08", "kind": "we", "part": "Written Expression", "tokens": ["The climate in the highlands is ", "more", " cooler ", "than in the lowlands", "."], "marks": [0, 1, 2, 3], "answer": "B", "explanation": "'Cooler' sudah bentuk comparative, jadi tidak boleh ditambah 'more' lagi. Cukup 'is cooler than'.", "topic": "comparative (double comparative)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 73, $${"id": "WE-09", "kind": "we", "part": "Written Expression", "tokens": ["The witness ", "could not", " hardly ", "see the suspect's face in the dark", "."], "marks": [0, 1, 2, 3], "answer": "C", "explanation": "Satu klausa tidak boleh memuat dua penanda negatif. 'Could not' dan 'hardly' sama-sama negatif, jadi salah satunya harus dibuang; yang lazim dibuang adalah 'hardly'.", "topic": "double negative"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 74, $${"id": "WE-10", "kind": "we", "part": "Written Expression", "tokens": ["Equipments", " for the experiment ", "is", " stored in the warehouse", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "'Equipment' termasuk uncountable noun, tidak punya bentuk jamak 'equipments'. Bentuk yang benar tetap 'equipment', dan verb 'is' di bagian C memang sudah cocok untuk subjek singular.", "topic": "countable/uncountable noun"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 75, $${"id": "WE-11", "kind": "we", "part": "Written Expression", "tokens": ["Although the movie was long", ", ", "but", " the audience stayed until the end", "."], "marks": [0, 1, 2, 3], "answer": "C", "explanation": "'Although' dan 'but' tidak boleh dipakai bersamaan karena maknanya bertabrakan. Cukup salah satu; di sini 'but'-nya yang dibuang.", "topic": "conjunction (redundant)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 76, $${"id": "WE-12", "kind": "we", "part": "Written Expression", "tokens": ["The novel was ", "wrote", " by a famous author ", "in 1960", "."], "marks": [0, 1, 2, 3], "answer": "B", "explanation": "Kalimat pasif memakai pola be + past participle. Setelah 'was' harusnya 'written', bukan 'wrote' yang merupakan bentuk past tense aktif.", "topic": "passive voice"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 77, $${"id": "WE-13", "kind": "we", "part": "Written Expression", "tokens": ["The children ", "enjoy", " spending their weekends ", "to play", " football with friends", "."], "marks": [0, 1, 2, 3], "answer": "D", "explanation": "Setelah frasa 'spend (time)' harus diikuti gerund, jadi 'to play' harus diganti 'playing'.", "topic": "gerund after verb phrase"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 78, $${"id": "WE-14", "kind": "we", "part": "Written Expression", "tokens": ["The bouquet ", "of flowers on the table ", "were", " a gift from her friend", "."], "marks": [0, 1, 2, 3], "answer": "C", "explanation": "Subjeknya 'the bouquet' yang tunggal; frasa 'of flowers on the table' hanya sisipan dan tidak mengubah verb. Jadi harusnya 'was', bukan 'were'.", "topic": "subject-verb agreement"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 79, $${"id": "WE-15", "kind": "we", "part": "Written Expression", "tokens": ["The ", "confident", " of the team grew ", "after their first victory", "."], "marks": [0, 1, 2, 3], "answer": "B", "explanation": "Yang dibutuhkan di posisi subjek adalah kata benda: 'confidence'. 'Confident' adalah adjective, jadi salah dipakai di sini.", "topic": "word form (noun)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 80, $${"id": "WE-16", "kind": "we", "part": "Written Expression", "tokens": ["The reason ", "why she resigned ", "was", " because", " she found a better job", "."], "marks": [0, 1, 2, 3], "answer": "D", "explanation": "Pola yang baku adalah 'the reason ... was that ...'. Memakai 'because' setelah 'the reason ... was' dianggap tidak tepat dalam tes ini.", "topic": "word choice (conjunction)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 81, $${"id": "WE-17", "kind": "we", "part": "Written Expression", "tokens": ["An", " university in the capital ", "offers", " scholarships to outstanding students", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "'University' diawali bunyi konsonan /j/, jadi artikelnya 'a', bukan 'an'.", "topic": "articles"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 82, $${"id": "WE-18", "kind": "we", "part": "Written Expression", "tokens": ["The scientist ", "discovered", " a new species and ", "names", " it after his mentor", "."], "marks": [0, 1, 3, 4], "answer": "C", "explanation": "Rangkaian kejadian lampau harus konsisten memakai past tense. 'Discovered' sudah past, jadi 'names' harus diganti 'named'.", "topic": "verb tense consistency"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 83, $${"id": "WE-19", "kind": "we", "part": "Written Expression", "tokens": ["The committee will announce ", "it's", " decision ", "tomorrow morning", "."], "marks": [0, 1, 2, 3], "answer": "B", "explanation": "Yang dibutuhkan adalah possessive adjective 'its' (miliknya). 'It's' adalah singkatan dari 'it is', jadi salah di sini.", "topic": "pronoun (its vs it's)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 84, $${"id": "WE-20", "kind": "we", "part": "Written Expression", "tokens": ["Most tall", " of the two brothers ", "plays", " basketball professionally", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "Karena yang dibandingkan hanya dua orang ('the two brothers'), harus memakai comparative 'the taller', bukan superlative 'most tall'.", "topic": "comparative vs superlative"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 85, $${"id": "WE-21", "kind": "we", "part": "Written Expression", "tokens": ["If she had studied harder, ", "she", " would have ", "pass", " the exam", "."], "marks": [0, 1, 2, 3], "answer": "D", "explanation": "Ini conditional type 3 dengan pola 'would have + past participle'. Jadi 'pass' harus diganti 'passed'.", "topic": "verb form (conditional)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 86, $${"id": "WE-22", "kind": "we", "part": "Written Expression", "tokens": ["In spite", " the rain, ", "the game", " continued until the evening", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "Frasa yang baku adalah 'in spite of', bukan 'in spite' saja. Kata 'of'-nya tidak boleh hilang.", "topic": "preposition collocation"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 87, $${"id": "WE-23", "kind": "we", "part": "Written Expression", "tokens": ["Honest", " is ", "the best policy", " in business", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "Posisi subjek harus diisi kata benda: 'honesty'. 'Honest' adalah adjective sehingga tidak bisa menjadi subjek kalimat.", "topic": "word form (noun as subject)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 88, $${"id": "WE-24", "kind": "we", "part": "Written Expression", "tokens": ["Walking through the park", ", ", "the flowers", " looked beautiful", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "Frasa 'walking through the park' menggantung karena subjek kalimatnya 'the flowers': bunga tidak bisa berjalan. Pelaku pada frasa pembuka harus sama dengan subjek kalimat.", "topic": "dangling modifier"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 89, $${"id": "WE-25", "kind": "we", "part": "Written Expression", "tokens": ["Between ", "you", " and ", "I", ", the test was quite difficult", "."], "marks": [0, 1, 2, 3], "answer": "D", "explanation": "Setelah preposisi harus memakai objective pronoun. Jadi 'between you and I' salah; yang benar 'between you and me'.", "topic": "pronoun case"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 90, $${"id": "RD-01", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "What is the main idea of the passage?", "options": ["The Silk Road was a vast network of exchange that shaped cultures, knowledge, and history far beyond the trade in silk.", "Ferdinand von Richthofen was the first European to travel the Silk Road.", "The Black Death was the most important event in the history of the Silk Road.", "China's Belt and Road Initiative is a complete reconstruction of the ancient Silk Road."], "answer": 0, "explanation": "Gagasan utama harus merangkum seluruh teks: jaringan pertukaran barang, ilmu, dan penyakit serta warisannya (paragraf 1-4). Pilihan B salah karena Richthofen hanya memberi nama, tidak bepergian. Pilihan C terlalu sempit karena wabah hanya dibahas di paragraf 3. Pilihan D salah karena teks menyebut inisiatif modern hanya 'echo' (menggema), bukan rekonstruksi penuh.", "qtype": "main idea"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 91, $${"id": "RD-02", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "According to the passage, the term 'Silk Road' was coined by", "options": ["a Chinese emperor of the Han dynasty", "a German geographer in the nineteenth century", "the Italian merchant Marco Polo", "UNESCO in 2014"], "answer": 1, "explanation": "Paragraf 1 menyatakan bahwa geografer Jerman Ferdinand von Richthofen memberi nama itu pada tahun 1877. Pilihan A, C, dan D tidak pernah disebut dalam teks.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 92, $${"id": "RD-03", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "The word 'consequential' in paragraph 2 is closest in meaning to", "options": ["temporary", "fragile", "significant", "accidental"], "answer": 2, "explanation": "Konteksnya: 'the most consequential cargo... was not a luxury fabric but knowledge'. Kata ini berarti paling berpengaruh atau penting, jadi 'significant'. 'Temporary' (sementara) dan 'fragile' (rapuh) tidak cocok, sedangkan 'accidental' (kebetulan) justru berlawanan makna.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 93, $${"id": "RD-04", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "According to paragraph 2, which of the following traveled eastward along the Silk Road?", "options": ["Papermaking", "Gunpowder", "The magnetic compass", "Buddhism"], "answer": 3, "explanation": "Paragraf 2 menjelaskan bahwa pembuatan kertas, bubuk mesiu, dan kompas bergerak ke arah barat (westward) dari China, sedangkan agama Buddha bergerak dari India ke China, yaitu ke arah timur (eastward).", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 94, $${"id": "RD-05", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "The word 'they' in paragraph 3 refers to", "options": ["distant populations", "the caravans", "historians", "new dangers"], "answer": 1, "explanation": "Kata 'they' merujuk pada subjek kalimat sebelumnya, yaitu 'The same caravans'. Pilihan C ('historians') adalah subjek kalimat itu sendiri, bukan acuannya, sedangkan A dan D tidak sesuai secara logika.", "qtype": "pronoun reference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 95, $${"id": "RD-06", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "It can be inferred from the passage that sea routes replaced the Silk Road mainly because they were", "options": ["faster and less expensive than overland caravans", "safer from the plague", "supported by the Chinese emperor", "shorter in distance than any land route"], "answer": 0, "explanation": "Paragraf 3 menyatakan kapal dapat memindahkan barang 'more quickly and cheaply than camel caravans'. Pilihan B tidak disebut sebagai alasan, sedangkan C dan D tidak didukung oleh teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 96, $${"id": "RD-07", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "According to the passage, all of the following were exchanged along the Silk Road EXCEPT", "options": ["silk", "Buddhist ideas", "papermaking techniques", "potatoes from the Americas"], "answer": 3, "explanation": "Sutra, gagasan Buddha, dan teknik pembuatan kertas semuanya disebut di paragraf 2. Kentang dari Amerika tidak pernah disebut dalam teks, dan secara historis memang bukan komoditas Jalur Sutra.", "qtype": "unstated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 97, $${"id": "RD-08", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "The passage states that the name 'Silk Road' is somewhat misleading because", "options": ["silk was never actually traded", "the routes were used only by the military", "it was a network of many routes rather than one road", "Richthofen never visited Asia"], "answer": 2, "explanation": "Paragraf 1 menegaskan 'there was never a single road', melainkan jaringan jalur karavan yang berubah-ubah. Pilihan A bertentangan dengan teks, sedangkan B dan D tidak pernah dinyatakan.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 98, $${"id": "RD-09", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "What does the author imply about the modern Belt and Road Initiative?", "options": ["It has fully restored trade along the ancient routes", "It deliberately recalls the corridors of the ancient network", "It was opposed by UNESCO", "It focuses only on the silk trade"], "answer": 1, "explanation": "Paragraf 4 menyebut proyek modern 'consciously echo the old corridors', artinya sengaja mengingatkan pada koridor kuno. Pilihan A terlalu berlebihan ('fully restored'), sedangkan C dan D tidak disebut dalam teks.", "qtype": "inference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 99, $${"id": "RD-10", "kind": "reading", "part": "Reading", "passageId": "RD-P1", "passageTitle": "The Silk Road: Exchange Beyond Silk", "passageText": "In 1877, the German geographer Ferdinand von Richthofen gave a name to one of history's greatest networks of exchange: the Silk Road. The label is convenient but slightly misleading, for there was never a single road. Instead, a shifting web of caravan tracks, mountain passes, and oasis towns linked China with Central Asia, India, Persia, and eventually the Mediterranean world. At its height, roughly from the second century BCE to the fifteenth century CE, this network carried goods, people, and ideas across some 6,400 kilometers of desert and steppe.\n\nSilk gave the routes their famous name, and Chinese silk was indeed prized by Roman elites willing to pay extraordinary prices. Yet the most consequential cargo traveling these roads was not a luxury fabric but knowledge. Papermaking, gunpowder, and the magnetic compass journeyed westward from China, eventually transforming warfare, navigation, and the spread of information in Europe. Moving in the opposite direction, Buddhism traveled from India into China, reshaping art, philosophy, and daily life, while merchants also carried glassware, music, new crops, and artistic styles in both directions.\n\nThe same caravans that enriched merchants also exposed distant populations to new dangers. Historians believe they played a role in carrying the bubonic plague westward in the fourteenth century, contributing to the devastation of the Black Death. The overland network eventually declined not because of disease but because of competition: after Portuguese navigators found a sea route around Africa at the end of the fifteenth century, ships could move goods between Asia and Europe more quickly and cheaply than camel caravans ever could.\n\nThe Silk Road's legacy endures. In 2014, UNESCO recognized part of the ancient network, the Chang'an-Tianshan Corridor, as a World Heritage site, and modern infrastructure projects such as China's Belt and Road Initiative consciously echo the old corridors. What began as a trade in luxury goods became, over fifteen centuries, one of humanity's first experiments in globalization.", "stem": "Why does the author mention Ferdinand von Richthofen in paragraph 1?", "options": ["To explain the origin of the term 'Silk Road'", "To criticize his geographical theories", "To compare him with Marco Polo", "To date the first caravan journey"], "answer": 0, "explanation": "Ia disebut dalam konteks pemberian nama 'Silk Road' pada tahun 1877, jadi fungsinya menjelaskan asal-usul istilah. Tidak ada kritik terhadap teorinya (B), perbandingan dengan Marco Polo (C), atau penanggalan karavan pertama (D).", "qtype": "purpose"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 100, $${"id": "RD-11", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "What is the main idea of the passage?", "options": ["The axolotl is the only animal that never reaches adulthood.", "Lake Xochimilco is the most polluted lake in Mexico.", "The axolotl's remarkable regenerative abilities make it both an endangered species and a valuable subject of scientific research.", "Scientists have learned how to make humans regenerate limbs."], "answer": 2, "explanation": "Gagasan utama mencakup dua sisi teks: kemampuan regenerasi luar biasa (paragraf 1-2), status terancam punah (paragraf 3), dan nilai risetnya (paragraf 4). Pilihan A salah karena teks tidak mengklaim axolotl satu-satunya hewan neoteni. Pilihan B tidak dibahas. Pilihan D salah karena teks menyebut para peneliti baru 'hope', belum berhasil.", "qtype": "main idea"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 101, $${"id": "RD-12", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "According to the passage, axolotls in the wild are found only in", "options": ["Lake Titicaca", "the Amazon River", "laboratory aquariums", "the canals of Lake Xochimilco"], "answer": 3, "explanation": "Paragraf 3 menyatakan axolotl liar 'survive only in the canals of Lake Xochimilco'. Pilihan C merujuk pada penangkaran, bukan alam liar, sedangkan A dan B tidak disebut.", "qtype": "stated detail"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 102, $${"id": "RD-13", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "The word 'revert' in paragraph 2 is closest in meaning to", "options": ["return", "advance", "divide", "disappear"], "answer": 0, "explanation": "Konteksnya: sel-sel 'revert to a less specialized state', artinya kembali ke keadaan semula, jadi 'return'. 'Advance' berlawanan makna, sedangkan 'divide' dan 'disappear' tidak sesuai konteks.", "qtype": "vocabulary"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 103, $${"id": "RD-14", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "The word 'They' in paragraph 3 refers to", "options": ["the canals", "axolotls", "scientists", "laboratories"], "answer": 1, "explanation": "Kata 'They' merujuk pada subjek kalimat sebelumnya, yaitu 'axolotls'. Pilihan A adalah habitatnya, bukan acuannya, sedangkan C dan D muncul belakangan dalam paragraf.", "qtype": "pronoun reference"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('reading', 'Reading', 104, $${"id": "RD-15", "kind": "reading", "part": "Reading", "passageId": "RD-P2", "passageTitle": "The Axolotl: Master of Regeneration", "passageText": "The axolotl, a salamander native to the lakes around Mexico City, looks like a creature that never finished growing up, and in a sense it never did. Through a phenomenon called neoteny, it retains its larval features, including feathery external gills, throughout its adult life. But the axolotl's strangest trait is not its appearance. It can regrow lost limbs, jaws, and portions of its spinal cord, and even repair damaged sections of its heart and brain, all without forming scars.\n\nWhen an axolotl loses a limb, cells near the wound revert to a less specialized state and gather into a structure called a blastema, a mass of unspecialized cells that gradually rebuilds the missing part, bone, muscle, nerves, and skin, in the correct arrangement. Mammals respond to serious injury very differently: their wounds close quickly but with scar tissue, and complex structures are never rebuilt. Researchers believe that differences in the immune response, particularly in how certain immune cells behave at the wound site, help explain why the axolotl regenerates while humans merely scar.\n\nIronically, this master of regeneration is disappearing from its natural home. In the wild, axolotls survive only in the canals of Lake Xochimilco, where they have been driven to the brink of extinction by pollution, the draining of their habitat, and introduced predators such as tilapia and carp. They are now classified as critically endangered. In laboratories and aquariums around the world, however, they thrive, bred by the thousands for research and the pet trade.\n\nThat contrast is precisely what makes the axolotl so valuable to science. By comparing its scar-free healing with our own, researchers hope to uncover therapies that could one day help human wounds heal more completely. The effort gained a powerful tool in 2018, when scientists sequenced the axolotl genome, all 32 billion base pairs of it, roughly ten times the size of the human genome and the largest genome sequenced at that time. Hidden within that enormous instruction book may be the secrets of regeneration itself.", "stem": "According to the passage, the axolotl genome", "options": ["was sequenced before the human genome", "is the smallest genome ever sequenced", "is identical in all salamander species", "was sequenced in 2018 and is about ten times larger than the human genome"], "answer": 3, "explanation": "Paragraf 4 menyatakan genom axolotl disekuensing pada 2018, berukuran 32 miliar pasangan basa, kira-kira sepuluh kali genom manusia, dan terbesar saat itu. Pilihan A, B, dan C bertentangan dengan informasi tersebut.", "qtype": "stated detail"}$$::jsonb);
